async function stopChild({ child, exited }, stopGraceMs) {
  child.kill('SIGTERM');
  const timedOut = await waitForExitOrTimeout(exited, stopGraceMs);
  if (timedOut) {
    child.kill('SIGKILL');
    await exited;
  }
}

/** Resolves `false` once `exited` settles, or `true` after `ms` - whichever comes first. */
async function waitForExitOrTimeout(exited, ms) {
  const controller = new AbortController();
  const timedOut = delay(ms, true, { signal: controller.signal }).catch(() => false);
  const result = await Promise.race([exited.then(() => false), timedOut]);
  controller.abort();
  return result;
}

function prefixOutput(child, name) {
  const label = `[${name}]`.padEnd(9);
  const forward = (stream, sink) => {
    let buffered = '';
    stream.on('data', (chunk) => {
      buffered += chunk;
      const lines = buffered.split('\n');
      buffered = lines.pop() ?? '';
      for (const line of lines) {
        sink.write(`${label} ${line}\n`);
      }
    });
  };
  forward(child.stdout, process.stdout);
  forward(child.stderr, process.stderr);
}
